-- 1. ADD COLUMNS IF NOT EXISTS (Safety measure)
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role TEXT DEFAULT 'user';
ALTER TABLE public.levels ADD COLUMN IF NOT EXISTS yield_rate DECIMAL(6,5) DEFAULT 1.0;

-- 2. SET FIRST USER TO ADMIN
UPDATE public.profiles 
SET role = 'admin', is_admin = true
WHERE id = (SELECT id FROM public.profiles ORDER BY created_at ASC LIMIT 1);

-- 3. RESET LEVELS & TASKS
TRUNCATE TABLE public.user_tasks CASCADE;
TRUNCATE TABLE public.task_items RESTART IDENTITY CASCADE;
DELETE FROM public.levels;

